// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint128 amount1, uint128 amount2, address actor) public {
        vm.assume(actor != address(0));
        amount1 = uint128(bound(amount1, 1, 1 ether));
        amount2 = uint128(bound(amount2, 1, 1 ether));

        vm.deal(actor, uint256(amount1) + uint256(amount2));

        vm.prank(actor);
        c.Put{value: amount1}(0);
        vm.prank(actor);
        c.Put{value: amount2}(0);

        (, uint bal) = c.Acc(actor);
        assertTrue(bal == uint256(amount1) + uint256(amount2));
    }
}
